"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["71509"],{7634(e,i,t){t.r(i),t.d(i,{metadata:()=>a,default:()=>u,frontMatter:()=>c,contentTitle:()=>l,toc:()=>d,assets:()=>h});var a=JSON.parse('{"id":"nhcx/v1/api/eligibility/endpoints/eligibility-v1-coverageeligibility-check","title":"Coverage eligibility check","description":"Provider asks the payer, via NHCX, whether a beneficiary\'s policy is in force, what it covers and which documents a preauth will need.","source":"@site/docs/nhcx/v1/api/eligibility/endpoints/eligibility-v1-coverageeligibility-check.mdx","sourceDirName":"nhcx/v1/api/eligibility/endpoints","slug":"/nhcx/v1/api/eligibility/endpoints/eligibility-v1-coverageeligibility-check","permalink":"/docs/pr-10/docs/nhcx/v1/api/eligibility/endpoints/eligibility-v1-coverageeligibility-check","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Coverage eligibility check","sidebar_label":"Coverage eligibility check","sidebar_class_name":"api-method api-method--post","description":"Provider asks the payer, via NHCX, whether a beneficiary\'s policy is in force, what it covers and which documents a preauth will need.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-eligibility.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-10/docs/nhcx/v1/api/eligibility/"},"next":{"title":"Coverage eligibility callback","permalink":"/docs/pr-10/docs/nhcx/v1/api/eligibility/endpoints/eligibility-v1-coverageeligibility-on-check"}}'),r=t(62540),n=t(43023),s=t(70862),o=JSON.parse('{"id":"eligibility_v1_coverageeligibility_check","module":"Coverage eligibility","moduleId":"eligibility","kind":"operation","method":"POST","path":"/v1/coverageeligibility/check","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."}],"summary":"Coverage eligibility check","description":"Provider asks the payer, via NHCX, whether a beneficiary\'s policy is in force, what it covers and which documents a preauth will need.\\n\\n### Business purpose\\n\\nCoverage eligibility is the pre-check a hospital desk runs before committing a patient to a cashless pathway. It confirms three things the desk needs: that the policy is active, what benefits and wallet balance are available, and whether a specific procedure needs authorisation at all. A rejection that would otherwise surface days later at preauth or claim adjudication surfaces in seconds while the patient is still at the counter, which benefits the hospital (less rework), the payer (fewer malformed preauths) and the patient (earlier certainty).\\n\\n### When to use\\n\\nCall it at registration or admission, before /v1/preauth/submit. The CoverageEligibilityRequest.purpose field (1..*) decides what the payer computes: discovery is the fallback when /participant/get/policies does not yield a policy code; validation retrieves used amount, available balance and wallet liability; auth-requirements checks whether a chosen procedure is covered at this hospital and returns the STG questionnaires and MAND document codes the preauth must carry; benefits is also listed. Send x-hcx-status request.initiated. No eligibility-specific workflow code is published in the workflow tables; the workbook sample shows x-hcx-workflow_id 11 (PATIENT_ADMITTED). For PMJAY an unspecified procedure still requires an auth-requirements check.\\n\\n### Preconditions\\n\\n- The provider is an onboarded NHCX participant (otherwise NHCX-1002) holding a valid Bearer token from the client-credentials session call; tokens expire after 1200 seconds.\\n- The payer\'s public certificate has been fetched via /fetch/certs (cache 24 hours) and the bundle is JWE-encrypted with RSA-OAEP-256 and A256GCM.\\n- x-hcx-recipient_code is the processingID from the get/policies response, not the PayerID.\\n- x-hcx-correlation_id is a fresh UUID for this request cycle; x-hcx-api_call_id is unique per call.\\n- The bundle contains the Patient (PMJAY Member ID and/or ABHA number), the Coverage record, both Organisations (provider and insurer) and a PractitionerRole for the enterer; items are included when purpose is auth-requirements.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth are all present.\\n\\n### Postconditions\\n\\nNHCX replies synchronously with HTTP 202 Accepted and a StatusSuccessResponse acknowledgement (timestamp, api_call_id, correlation_id, result with sender_code, recipient_code, entity_type coverageeligibility and protocol_status such as request.queued or request.dispatched, plus an empty error object). The 202 means only that the JWE structure and open protocol headers validated; the gateway then forwards the request to the payer asynchronously. The eligibility answer arrives later on the provider\'s /v1/coverageeligibility/on_check endpoint as a CoverageEligibilityResponseBundle, or as a ProtocolResponse carrying x-hcx-error_details, or as a redirect or forward instruction to try another payer. Other documented statuses are 400 request validation failed, 404 resource not found and 500 downstream systems down.\\n\\n### Common mistakes\\n\\n- Treating the 202 as the eligibility answer instead of waiting for the on_check callback; NHCX never returns a synchronous FHIR decision.\\n- Using the PayerID from get/policies as x-hcx-recipient_code instead of the processingID (NHCX-1003 receiver not registered).\\n- Reusing a correlation ID from an earlier cycle (NHCX-1006 duplicate request) or retrying a failed cycle under the same ID, which NHCX has already marked inactive.\\n- Sending the wrong status string; only request.initiated is accepted on an initiating request (NHCX-1011).\\n- Payer-side business rejections such as PAYR-1113 invalid item code, PAYR-1115 quantity not greater than 1, PAYR-1116 hospital not authorised for the policy, PAYR-1117 or PAYR-1122 no policy details, PAYR-1123 beneficiary not a covered member, and PAYR-1014 date of birth after date of service.\\n- Omitting the Accept header on the HTTP call.\\n\\n### Best practices\\n\\n- Persist the correlation ID against the patient episode before posting; it is the only key for matching the callback.\\n- Refresh the token automatically before the 1200-second expiry and treat a 401 as refresh-and-retry-once.\\n- Run discovery first only when get/policies gives no policy code, then validation, then auth-requirements for the chosen package; store the returned MAND codes and STG questionnaire references and attach them to the preauth.\\n- Do not assume the response echoes your request codes: items come back in the payer\'s numeric master codes (for example 100478 against your MG003B).\\n- Use IST timestamps with the +05:30 offset in the protected header.\\n- Log the 202 body (protocol_status, api_call_id) so a missing callback can be traced with /v1/status.\\n\\n### Related scenario\\n\\nA patient arrives at a district hospital with a PMJAY card. The desk calls /participant/get/policies and receives a processingID for the state health agency. Because the treating doctor wants a corneal grafting package, the desk builds a CoverageEligibilityRequest with purpose validation and auth-requirements, encrypts it for the payer and posts it to /v1/coverageeligibility/check, receiving a 202 with protocol_status request.queued. Minutes later the payer\'s answer lands on /v1/coverageeligibility/on_check with inforce true, authorizationRequired true and MAND0409 and MAND0104 listed as supporting documents. The desk collects those documents and proceeds to /v1/preauth/submit under workflow 12.\\n\\n### Specification\\n\\nChapter [Coverage eligibility request](/docs/nhcx/v1/reference/fhir/coverage-eligibility-request) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"11","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"request.initiated","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"202","description":"NHCX replies synchronously with HTTP 202 Accepted and a StatusSuccessResponse acknowledgement (timestamp, api_call_id, correlation_id, result with sender_code, recipient_code, entity_type coverageeligibility and protocol_status such as request.queued or request.dispatched, plus an empty error object).","example":{"timestamp":"19/03/2026 11:46:35:120","api_call_id":"a1b2c3d4-e5f6-7890-abcd-ef1234567890","correlation_id":"11223344-5566-7788-99aa-bbccddeeff00","result":{"sender_code":"1000004446@hcx","recipient_code":"1518@hcx","entity_type":"coverageeligibility","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Coverage eligibility","tagDescription":"Coverage eligibility is the pre-check a hospital desk runs before committing a patient to a cashless pathway.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/coverageeligibility/check \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 11\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}\'"}');let c={title:"Coverage eligibility check",sidebar_label:"Coverage eligibility check",sidebar_class_name:"api-method api-method--post",description:"Provider asks the payer, via NHCX, whether a beneficiary's policy is in force, what it covers and which documents a preauth will need.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-eligibility.yaml",generated:!0},l,h={},d=[{value:"Callbacks",id:"callbacks",level:2}];function p(e){let i={a:"a",code:"code",h2:"h2",li:"li",strong:"strong",ul:"ul",...(0,n.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(s.A,{operation:o}),"\n",(0,r.jsx)(i.h2,{id:"callbacks",children:"Callbacks"}),"\n",(0,r.jsxs)(i.ul,{children:["\n",(0,r.jsxs)(i.li,{children:["After this call, ABDM posts ",(0,r.jsx)(i.strong,{children:"Receive coverage eligibility check"})," to ",(0,r.jsx)(i.code,{children:"v1_coverageeligibility_check"}),". ",(0,r.jsx)(i.a,{href:"/docs/nhcx/v1/api/eligibility/endpoints/eligibility-webhook-v1-coverageeligibility-check",children:"Open the callback"}),"."]}),"\n"]})]})}function u(e={}){let{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,r.jsx)(i,{...e,children:(0,r.jsx)(p,{...e})}):p(e)}}}]);